    except Exception:
        return []
    out=[]; i=0; n=len(lines)
    while i<n:
        if lines[i].startswith('{') and i>0:
            k=i-1
            while k>i-8 and k>=0 and ')' not in lines[k]:
                k-=1
            sig=' '.join(lines[max(0,k):i]) if k>=0 else ''
            m=re.search(r"([A-Za-z_]\w*)\s*\(", sig)
            name=m.group(1) if m else None
